  /**
   * What it says when there is nothing; empty is Nothing here yet.
   *
   * @default ""
   */
  readonly emptyLabel?: string;
  /**
   * A line under it (what to do).
   *
   * @default ""
   */
  readonly emptyHint?: string;
  /**
   * The error has a Retry button.
   *
   * @default true
   */
